# frozen_string_literal: true

# Generated by rowstile client from the policy. Do not edit; re-run after changing the policy.
# The policy's names, for the Ruby SDK (the rowstile gem). With their signatures (rowstile client rbs),
# Steep refuses a misspelled type or permission: Authz::Note::EDIT, Authz.queries.can("note", 1, "edit").
module Authz
  PERMISSIONS = {
    "project" => ["edit", "view"].freeze,
    "note" => ["edit", "view"].freeze,
    "message" => ["read"].freeze,
    "folder" => ["edit"].freeze,
  }.freeze
  # relations people may share with authz.share(), and with whom (subject type, or type#relation)
  SHARED_RELATIONS = {
  }.freeze
  SCOPES = [].freeze

  module Project
    TYPE = "project"
    EDIT = "edit"
    VIEW = "view"
  end

  module Note
    TYPE = "note"
    EDIT = "edit"
    VIEW = "view"
  end

  module Message
    TYPE = "message"
    READ = "read"
  end

  module Folder
    TYPE = "folder"
    EDIT = "edit"
  end

  # the SDK's questions (can, perms_of, permitted), taking only the policy's names
  def self.queries = Rowstile::Queries.new
end
